        this.MAX_PARTICLES = 2900;
        this.MAX_FOAM_PARTICLES = 180;
        this.VELOCITY_DAMPING = 0.998;
        this.GRAVITY = new Vector2(0, 2.45);
        this.REST_DENSITY = 7.1;
        this.K_NEAR = 5.6;
        this.K = 0.62;
        this.INTERACTION_RADIUS = 16;

        this.SIGMA = 0.075;
        this.BETA = 0.025;

