        // CO2 and whips up foam; foam is buoyant and rises into a head; it slowly decays.
        this.FOAM_THRESHOLD = 260;  // turbulence above this whips up foam
        this.FOAM_GEN = 0.018;      // how fast agitation turns into foam
        this.FOAM_DECAY = 0.004;    // surface head lingers; buried foam clears much faster
        this.FOAM_BUOYANCY = 1.6;   // foamy beer floats up to form the head
        this.FOAM_RENDER_MIN = 0.16;

        this.BOTTLE_CAPACITY_L = 1.0;
        this.GLASS_CAPACITY_L = 0.5;
