    }

    /* ---------- Bottle geometry ---------- */

    updateBottleFromPour(){
        let b = this.bottle;
        let totalLength = b.neckLength + b.bodyLength;
        let axis = new Vector2(Math.cos(b.angle), Math.sin(b.angle));
        let mouth = Sub(b.center, Scale(axis, totalLength * 0.5));
        let mouthOut = Scale(axis, -1);

        // How strongly the mouth points downward -> how fast it pours.
        let downward = Math.max(0, mouthOut.y);
        let tiltFlow = Math.max(0, Math.min(1, (downward - 0.06) / 0.6));
