        this.emitter.velocity = 60 + this.pourAmount * 30;
        this.emitter.spread = 0.02 + this.pourAmount * 0.035;
    }

    smoothStep(t){
        return t * t * (3 - 2 * t);
    }

    bottleLocalToWorld(local){
        let axis = this.bottle.axis;
        let normal = axis.GetNormal();
        normal.Normalize();
        let bodyCenter = Add(this.bottle.mouth, Scale(axis, this.bottle.neckLength + this.bottle.bodyLength * 0.5));
        return Add(bodyCenter, Add(Scale(normal, local.x), Scale(axis, local.y)));

