class WebGPUBeerSolver{
    constructor(device, config){
        this.device = device;
        this.maxParticles = config.maxParticles;
        this.particleStride = 16;
        this.particleByteSize = this.maxParticles * this.particleStride * 4;
        this.workgroupSize = 64;

        this.volumeCellSize = config.volumeCellSize;
        this.volumeGridWidth = Math.ceil(config.canvasWidth / this.volumeCellSize);
        this.volumeGridHeight = Math.ceil(config.canvasHeight / this.volumeCellSize);
        this.volumeGridCells = this.volumeGridWidth * this.volumeGridHeight;
        this.volumeByteSize = this.volumeGridCells * 4;

        this.uploadScratch = new Float32Array(this.maxParticles * this.particleStride);
        this.readScratch = new Float32Array(this.maxParticles * this.particleStride);
        this.volumeFractions = new Float32Array(this.volumeGridCells);
        this.params = new Float32Array(40);

        this.particleBuffer = device.createBuffer({
            size: this.particleByteSize,
            usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST | GPUBufferUsage.COPY_SRC
        });
        this.particleReadbackBuffer = device.createBuffer({
            size: this.particleByteSize,
            usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST
        });
        this.paramsBuffer = device.createBuffer({
            size: this.params.byteLength,
            usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST
        });
        this.volumeCountBuffer = device.createBuffer({
            size: this.volumeByteSize,
            usage: GPUBufferUsage.STORAGE
        });
        this.volumeFractionBuffer = device.createBuffer({
            size: this.volumeByteSize,
            usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC
        });
        this.volumeReadbackBuffer = device.createBuffer({
            size: this.volumeByteSize,
            usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST
        });

        this.createPipelines();
    }

    static async create(config){
        if(!navigator.gpu){
            throw new Error("WebGPU is required for this simulation.");
        }

        let adapter = await navigator.gpu.requestAdapter({
            powerPreference: "high-performance"
        });
        if(!adapter){
            throw new Error("No WebGPU adapter was found.");
        }

        let device = await adapter.requestDevice();
        device.lost.then((info) => {
            console.error("WebGPU device lost:", info.message);
        });

        return new WebGPUBeerSolver(device, config);
    }

    createPipelines(){
        let module = this.device.createShaderModule({ code: this.shaderCode() });
        this.bindGroupLayout = this.device.createBindGroupLayout({
            entries: [
                { binding: 0, visibility: GPUShaderStage.COMPUTE, buffer: { type: "storage" } },
                { binding: 1, visibility: GPUShaderStage.COMPUTE, buffer: { type: "uniform" } },
                { binding: 2, visibility: GPUShaderStage.COMPUTE, buffer: { type: "storage" } },
                { binding: 3, visibility: GPUShaderStage.COMPUTE, buffer: { type: "storage" } }
            ]
        });
        let layout = this.device.createPipelineLayout({ bindGroupLayouts: [this.bindGroupLayout] });

        let makePipeline = (entryPoint) => this.device.createComputePipeline({
            layout: layout,
            compute: { module: module, entryPoint: entryPoint }
        });

        this.pipelines = {
            predict: makePipeline("predict"),
            density: makePipeline("density"),
            solve: makePipeline("solve"),
            applyDelta: makePipeline("applyDelta"),
            finalizeParticles: makePipeline("finalizeParticles"),
            clearVolume: makePipeline("clearVolume"),
            accumulateVolume: makePipeline("accumulateVolume"),
            finalizeVolume: makePipeline("finalizeVolume")
        };

        this.bindGroup = this.device.createBindGroup({
            layout: this.bindGroupLayout,
            entries: [
                { binding: 0, resource: { buffer: this.particleBuffer } },
                { binding: 1, resource: { buffer: this.paramsBuffer } },
                { binding: 2, resource: { buffer: this.volumeCountBuffer } },
                { binding: 3, resource: { buffer: this.volumeFractionBuffer } }
            ]
        });
    }

    uploadParticles(particles){
        let count = Math.min(particles.length, this.maxParticles);
        for(let i=0; i<count; i++){
            let p = particles[i];
            let o = i * this.particleStride;
            this.uploadScratch[o + 0] = p.position.x;
            this.uploadScratch[o + 1] = p.position.y;
            this.uploadScratch[o + 2] = p.prevPosition.x;
            this.uploadScratch[o + 3] = p.prevPosition.y;
            this.uploadScratch[o + 4] = p.velocity.x;
            this.uploadScratch[o + 5] = p.velocity.y;
            this.uploadScratch[o + 6] = p.foam || 0;
            this.uploadScratch[o + 7] = p.agitation || 0;
            this.uploadScratch[o + 8] = p.cover || 0;
            this.uploadScratch[o + 9] = p.age || 0;
            this.uploadScratch[o + 10] = p.lambda || 0;
