    var vel = (p.pos - p.prev) / dt;
    let h = params.fluid0.x;

    for(var j: u32 = 0u; j < particleCount(); j = j + 1u){
        if(j == i){
            continue;
        }
        let pj = particles[j];
        let r = p.pos - pj.pos;
        let dist = length(r);
        if(dist < h && dist > 0.0001){
