        return;
    }

    let pi = particles[i];
    let h = params.fluid0.x;
    var rho = 1.0;
    var gradSum = 0.0;
    var gradI = vec2<f32>(0.0);

    for(var j: u32 = 0u; j < particleCount(); j = j + 1u){
        if(j == i){
            continue;
        }
        let pj = particles[j];
        let r = pi.pos - pj.pos;
        let dist = length(r);
        if(dist < h){
            rho += kernelWeight(dist, h);
            let g = gradKernel(r, h) / params.fluid0.y;
            gradSum += dot(g, g);
            gradI += g;
        }
    }

    gradSum += dot(gradI, gradI);
    let c = max(rho / params.fluid0.y - 1.0, 0.0);
    var p = pi;
    p.solverDensity = rho / params.fluid0.y;
    p.lambda = -c / (gradSum + params.fluid0.z);
    particles[i] = p;
}

