            continue;
        }
        let pj = particles[j];
        let r = pi.pos - pj.pos;
        let dist = length(r);
        if(dist < h && dist > 0.0001){
            let q = max(0.0, 1.0 - dist / h);
            let corr = artificialPressure(dist, h);
            delta += (pi.lambda + pj.lambda + corr) * gradKernel(r, h);
            delta.y += (pi.materialDensity - pj.materialDensity) * q * params.density1.z;

            let n = (pj.pos - pi.pos) / dist;
            let normalSpeed = dot(pi.vel - pj.vel, n);
            agitation += q * abs(normalSpeed);
