fn clearVolume(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    let cells = u32(params.grid0.y) * u32(params.grid0.z);
    if(i >= cells){
        return;
    }
    atomicStore(&volumeCounts[i], 0u);
    atomicStore(&mixtureCounts[i], 0u);
    atomicStore(&densityCounts[i], 0u);
    volumeFractions[i] = 0.0;
    densityFractions[i] = 0.0;
}

