fn accumulateVolume(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    if(i >= particleCount()){
        return;
    }
    let p = particles[i];
    let cellSize = params.grid0.x;
    let gx = i32(floor(p.pos.x / cellSize));
    let gy = i32(floor(p.pos.y / cellSize));
    let gw = i32(params.grid0.y);
    let gh = i32(params.grid0.z);
    if(gx < 0 || gy < 0 || gx >= gw || gy >= gh){
        return;
