    let mixtureFixed = u32(params.grid0.w);
    let beerShare = clamp(1.0 - p.air * 0.72 - p.foam * 0.20, 0.12, 1.0);
    let beerFixed = u32(f32(mixtureFixed) * beerShare);
    let densityFixed = u32(f32(mixtureFixed) * clamp(p.materialDensity, 0.0, 1.25));
    atomicAdd(&volumeCounts[idx], beerFixed);
    atomicAdd(&mixtureCounts[idx], mixtureFixed);
    atomicAdd(&densityCounts[idx], densityFixed);
}

