        if(x < 0 || y < 0 || x >= this.gpu.volumeGridWidth || y >= this.gpu.volumeGridHeight){
            return 0;
        }
        return this.gpu.volumeFractions[y * this.gpu.volumeGridWidth + x];
    }

    getDensityFractionAt(position){
        if(!this.gpu || !this.gpu.densityFractions){
            return 0;
        }
        let x = Math.floor(position.x / this.gpu.volumeCellSize);
        let y = Math.floor(position.y / this.gpu.volumeCellSize);
        if(x < 0 || y < 0 || x >= this.gpu.volumeGridWidth || y >= this.gpu.volumeGridHeight){
            return 0;
        }
        return this.gpu.densityFractions[y * this.gpu.volumeGridWidth + x];
    }

    // Local Y of the beer surface inside the glass, derived from how full it is.
    getGlassSurfaceLocalY(){
        let fill = Math.max(0, Math.min(1.12, this.getGlassBeerVolumeL() / this.GLASS_CAPACITY_L));
        let bottom = this.glass.height * 0.5 - this.glass.wall;
        let usableHeight = this.glass.height * 0.82;
        return bottom - usableHeight * fill;
    }

    /* ---------- Bottle geometry ---------- */

    updateBottleFromPour(){
        let b = this.bottle;
        let totalLength = b.neckLength + b.bodyLength;
        let axis = new Vector2(Math.cos(b.angle), Math.sin(b.angle));
        let mouth = Sub(b.center, Scale(axis, totalLength * 0.5));
        let mouthOut = Scale(axis, -1);

        // How strongly the mouth points downward -> how fast it pours.
        let downward = Math.max(0, mouthOut.y);
        let tiltFlow = Math.max(0, Math.min(1, (downward - 0.06) / 0.6));
        tiltFlow = this.smoothStep(tiltFlow);

        let pourDir = Add(Scale(mouthOut, 1.15), new Vector2(0, 0.78));
        pourDir.Normalize();

        b.mouth = mouth;
        b.axis = axis;
        b.pourDir = pourDir;

        let volumeGate = Math.min(1, this.bottleVolumeL / 0.04);
        this.pourAmount = this.bottleVolumeL <= 0 ? 0 : tiltFlow * volumeGate;
        b.flowScale = this.pourAmount;

        // The stream starts a touch outside the lip so it reads as leaving the bottle.
        this.emitter.position = Add(mouth, Scale(pourDir, 6));
        this.emitter.direction = pourDir;
        this.emitter.flowScale = this.pourAmount;
        this.emitter.size = 3 + this.pourAmount * 3;
        this.emitter.amount = 1 + Math.round(this.pourAmount * 3);
        this.emitter.velocity = 60 + this.pourAmount * 30;
        this.emitter.spread = 0.02 + this.pourAmount * 0.035;
    }

    smoothStep(t){
        return t * t * (3 - 2 * t);
    }

    bottleLocalToWorld(local){
        let axis = this.bottle.axis;
        let normal = axis.GetNormal();
        normal.Normalize();
        let bodyCenter = Add(this.bottle.mouth, Scale(axis, this.bottle.neckLength + this.bottle.bodyLength * 0.5));
        return Add(bodyCenter, Add(Scale(normal, local.x), Scale(axis, local.y)));
    }

    // Outer half-width of the bottle silhouette at a given body-local Y.
    bottleHalfWidthOuter(localY){
        let b = this.bottle;
        let bodyTopY = -b.bodyLength * 0.5;
        let bodyBotY = b.bodyLength * 0.5;
        let mouthTipY = bodyTopY - b.neckLength;
        let neckHalf = b.neckWidth * 0.5;
        let bodyHalf = b.bodyWidth * 0.5;

        if(localY < bodyTopY){
            // neck (very slight taper toward the lip)
            let t = Math.max(0, Math.min(1, (localY - mouthTipY) / b.neckLength));
            return neckHalf * (0.9 + 0.1 * t);
        }
        if(localY < bodyTopY + b.shoulder){
            // shoulder: neck -> body
            let t = (localY - bodyTopY) / b.shoulder;
            return neckHalf + (bodyHalf - neckHalf) * this.smoothStep(t);
        }
        if(localY > bodyBotY - b.bottomRound){
            // rounded base corners
            let t = (bodyBotY - localY) / b.bottomRound; // 1 -> 0
            return bodyHalf * Math.sqrt(Math.max(0, 1 - (1 - t) * (1 - t)));
        }
        return bodyHalf;
    }

    // Trace the bottle silhouette (optionally inset) into the given ctx as a closed path.
    traceBottlePath(targetCtx, inset){
        let b = this.bottle;
        let bodyTopY = -b.bodyLength * 0.5;
        let bodyBotY = b.bodyLength * 0.5;
        let mouthTipY = bodyTopY - b.neckLength;
        let step = 6;
        let pts = [];

        for(let y = mouthTipY; y <= bodyBotY; y += step){
            let hw = Math.max(2, this.bottleHalfWidthOuter(y) - inset);
            pts.push(new Vector2(-hw, y));
        }
        for(let y = bodyBotY; y >= mouthTipY; y -= step){
            let hw = Math.max(2, this.bottleHalfWidthOuter(y) - inset);
            pts.push(new Vector2(hw, y));
        }

        targetCtx.beginPath();
        for(let i=0; i<pts.length; i++){
            let w = this.bottleLocalToWorld(pts[i]);
            if(i === 0){
                targetCtx.moveTo(w.x, w.y);
            }else{
                targetCtx.lineTo(w.x, w.y);
            }
        }
        targetCtx.closePath();
    }

    /* ---------- Simulation step ---------- */

    // The hand holding the glass straightens it up as it fills, like a real pour.
    updateGlassTilt(dt){
        let t = this.smoothStep(Math.min(1, this.getGlassFill01() * 1.7));
        let target = this.glass.restAngle + (this.glass.uprightAngle - this.glass.restAngle) * t;
        let ease = 1 - Math.pow(0.2, dt);
        this.glass.angle += (target - this.glass.angle) * ease;
        this.createGlass();
    }

    async update(dt, substeps = 1){
        if(!this.gpu){
            throw new Error("Simulation.update() requires an initialized WebGPU solver.");
        }

        this.frame++;
        this.updateBottleFromPour();

        this.glassVolL = this.getGlassBeerVolumeL();

        let maxSpawnFromBottle = Math.floor(this.bottleVolumeL / this.PARTICLE_LITERS);
        let spawned = this.emitter.spawn(dt * substeps, this.particles, this.MAX_PARTICLES, maxSpawnFromBottle);
        if(spawned > 0){
            this.bottleVolumeL = Math.max(0, this.bottleVolumeL - spawned * this.PARTICLE_LITERS);
        }

        let glassVolume = this.glassVolL;
        let overflow = Math.max(0, (glassVolume - this.GLASS_CAPACITY_L) / this.GLASS_CAPACITY_L);
        let rimOut = new Vector2(-0.78, -0.18);
        rimOut.Normalize();
        let tableY = this.glass.center.y + this.glass.height * 0.5 + 2;

        await this.gpu.step(this.particles, {
            dt: dt,
            substeps: substeps,
            solverIterations: this.RELAX_ITERS,
            canvasWidth: canvas.width,
            canvasHeight: canvas.height,
            gravity: this.GRAVITY,
            velocityDamping: this.VELOCITY_DAMPING,
            interactionRadius: this.INTERACTION_RADIUS,
            restDensity: this.REST_DENSITY,
            lambdaEpsilon: this.LAMBDA_EPSILON,
            pbfStrength: this.PBF_STRENGTH,
            viscosity: this.XSPH_VISCOSITY,
            artificialPressure: this.ARTIFICIAL_PRESSURE,
            artificialPressureRadius: this.ARTIFICIAL_PRESSURE_RADIUS,
            glass: this.glass,
            tableY: tableY,
            overflow: overflow,
            rimOut: rimOut,
            foamThreshold: this.FOAM_THRESHOLD,
            foamGeneration: this.FOAM_GEN,
            foamDecay: this.FOAM_DECAY,
            foamBuoyancy: this.FOAM_BUOYANCY,
            foamRenderMin: this.FOAM_RENDER_MIN,
            foamLiftLimit: this.FOAM_LIFT_LIMIT,
            particleVolumeRadius: this.PARTICLE_VOLUME_RADIUS,
            collisionRadius: this.COLLISION_RADIUS,
            frame: this.frame,
            baseDensity: this.BASE_DENSITY,
            airDensityDrop: this.AIR_DENSITY_DROP,
            airEntrapment: this.AIR_ENTRAINMENT,
            airVentRate: this.AIR_VENT_RATE,
            denseSettling: this.DENSE_SETTLING,
            aeratedLift: this.AERATED_LIFT,
            stratification: this.STRATIFICATION,
            densePacking: this.DENSE_PACKING
        });

        this.updateVolumeFractionStats();
        this.trimParticles();
    }

    trimParticles(){
        // Drop particles that have spilled off the table so they don't pile up forever.
        for(let i=this.particles.length - 1; i>=0; i--){
            let p = this.particles[i];
            if(p.position.y > canvas.height - 4 && !this.isInsideGlassInterior(p.position)){
                p.deadTimer = (p.deadTimer || 0) + 1;
                if(p.deadTimer > 90){
                    this.particles.splice(i, 1);
                }
            }
        }
        if(this.particles.length > this.MAX_PARTICLES){
            this.particles.splice(0, this.particles.length - this.MAX_PARTICLES);
        }
    }

    /* ---------- Rendering: beer & foam silhouettes (white on transparent) ---------- */

    drawBeer(targetCtx){
        let r = window.BEER_RADIUS;
        targetCtx.fillStyle = "white";
        targetCtx.globalAlpha = 1;

        for(let i=0; i < this.particles.length; i++){
            let p = this.particles[i];
            targetCtx.beginPath();
            targetCtx.arc(p.position.x, p.position.y, r, 0, Math.PI * 2);
            targetCtx.fill();
        }
    }

    drawFoam(targetCtx){
        targetCtx.fillStyle = "white";
        targetCtx.globalAlpha = 1;

        // The head IS the foamy beer particles, which buoyancy has floated to the top.
        // No scripted band - wherever foam physically is, that is where it draws.
        let r = window.FOAM_RADIUS;
        for(let i=0; i<this.particles.length; i++){
            let p = this.particles[i];
            if(p.foam <= this.FOAM_RENDER_MIN){
                continue;
            }
            let inGlass = this.isInsideGlassInterior(p.position);
            let surface = inGlass ? Math.max(0, 1 - p.cover * 0.32) : 0.18;
            if(surface <= 0.06){
                continue;
            }
            let f = Math.min(1, (p.foam - this.FOAM_RENDER_MIN) / (1 - this.FOAM_RENDER_MIN));
            f *= surface;
            let radiusScale = inGlass ? (0.55 + f * 0.6) : (0.20 + f * 0.28);
            targetCtx.globalAlpha = inGlass ? Math.max(0.15, Math.min(1, f * 1.25)) : Math.min(0.35, f * 0.9);
            targetCtx.beginPath();
            targetCtx.arc(p.position.x, p.position.y, r * radiusScale, 0, Math.PI * 2);
            targetCtx.fill();
        }
        targetCtx.globalAlpha = 1;

    }

    drawBeerDetails(targetCtx){
        targetCtx.save();

        // Density/air overlay from the GPU material state:
        // dense beer darkens and settles; aerated beer turns pale before becoming foam.
        for(let i=0; i<this.particles.length; i += 4){
            let p = this.particles[i];
            if(!this.isInsideGlassInterior(p.position)){
                continue;
            }

            let dense = Math.max(0, (p.density || 1) - 1);
            if(dense > 0.01){
                targetCtx.globalAlpha = Math.min(0.20, dense * 2.4);
                targetCtx.beginPath();
                targetCtx.arc(p.position.x, p.position.y + 2, 10, 0, Math.PI * 2);
                targetCtx.fillStyle = "#9f5204";
                targetCtx.fill();
            }

            let air = p.air || 0;
            if(air > 0.08){
                targetCtx.globalAlpha = Math.min(0.42, air * 0.55);
                targetCtx.beginPath();
                targetCtx.arc(p.position.x, p.position.y - 1, 9 + air * 8, 0, Math.PI * 2);
                targetCtx.fillStyle = "#fff1c5";
                targetCtx.fill();
            }

            if(i % 12 === 0){
                let bob = Math.sin(this.frame * 0.05 + i) * 2;
                let bubbleR = 1.1 + ((i * 17) % 5) * 0.4;
                targetCtx.globalAlpha = 0.22 + Math.min(0.45, (p.air || 0) * 0.7);
