            this.uploadScratch[o + 3] = p.prevPosition.y;
            this.uploadScratch[o + 4] = p.velocity.x;
            this.uploadScratch[o + 5] = p.velocity.y;
            this.uploadScratch[o + 6] = p.foam || 0;
            this.uploadScratch[o + 7] = p.air || 0;
            this.uploadScratch[o + 8] = p.density || 1;
            this.uploadScratch[o + 9] = p.age || 0;
            this.uploadScratch[o + 10] = p.agitation || 0;
            this.uploadScratch[o + 11] = p.cover || 0;
            this.uploadScratch[o + 12] = 0;
            this.uploadScratch[o + 13] = 0;
            this.uploadScratch[o + 14] = 0;
            this.uploadScratch[o + 15] = 0;
        }

        if(count > 0){
            this.device.queue.writeBuffer(
                this.particleBuffer,
                0,
                this.uploadScratch.buffer,
                0,
                count * this.particleStride * 4
