        }
        return count;
    }

    writeParams(settings){
        let p = this.params;
        let particleArea = Math.PI * settings.particleVolumeRadius * settings.particleVolumeRadius;
        let cellArea = this.gridCellSize * this.gridCellSize;
        let volumeFixedPoint = Math.max(1, Math.round((particleArea / cellArea) * 65535));

        p[0] = settings.dt;
        p[1] = settings.particleCount;
        p[2] = settings.canvasWidth;
        p[3] = settings.canvasHeight;
        p[4] = settings.gravity.x;
        p[5] = settings.gravity.y;
        p[6] = settings.maxSpeed;
        p[7] = settings.tableY;
        p[8] = this.gridCellSize;
        p[9] = this.gridWidth;
        p[10] = this.gridHeight;
        p[11] = volumeFixedPoint;
        p[12] = settings.picFlipBlend;
        p[13] = settings.gridDamping;
        p[14] = settings.pressureScale;
        p[15] = settings.maxParticles;
        p[16] = settings.glass.center.x;
        p[17] = settings.glass.center.y;
        p[18] = settings.glass.angle;
        p[19] = settings.glass.wall;
        p[20] = settings.glass.topWidth;
        p[21] = settings.glass.bottomWidth;
        p[22] = settings.glass.height;
        p[23] = settings.basePull;
        p[24] = settings.foamThreshold;
        p[25] = settings.foamGeneration;
        p[26] = settings.foamDecay;
        p[27] = settings.airEntrapment;
        p[28] = settings.airVentRate;
        p[29] = settings.airDensityDrop;
        p[30] = settings.foamBuoyancy;
        p[31] = settings.baseDensity;
        p[32] = settings.overflow;
        p[33] = settings.rimOut.x;
        p[34] = settings.rimOut.y;
        p[35] = 0;

        this.device.queue.writeBuffer(this.paramsBuffer, 0, p.buffer, 0, p.byteLength);
