    async step(particles, settings){
        let particleCount = this.uploadParticles(particles);
        settings.particleCount = particleCount;
        this.writeParams(settings);

        let encoder = this.device.createCommandEncoder();
        let particleWorkgroups = Math.max(1, Math.ceil(particleCount / this.workgroupSize));
        let gridWorkgroups = Math.max(1, Math.ceil(this.gridCells / this.workgroupSize));

        for(let s=0; s<settings.substeps; s++){
            encoder.copyBufferToBuffer(this.gridVelocityBuffer, 0, this.prevGridVelocityBuffer, 0, this.gridVecByteSize);
            this.dispatch(encoder, this.pipelines.clearGrid, gridWorkgroups);
            this.dispatch(encoder, this.pipelines.particleToGrid, particleWorkgroups);
            this.dispatch(encoder, this.pipelines.normalizeGrid, gridWorkgroups);
            this.dispatch(encoder, this.pipelines.divergence, gridWorkgroups);
            this.dispatch(encoder, this.pipelines.clearPressure, gridWorkgroups);
            for(let i=0; i<settings.pressureIterations; i++){
                this.dispatch(encoder, this.pipelines.pressureJacobi, gridWorkgroups);
            }
            this.dispatch(encoder, this.pipelines.subtractPressure, gridWorkgroups);
            this.dispatch(encoder, this.pipelines.gridToParticle, particleWorkgroups);
            this.dispatch(encoder, this.pipelines.advectParticles, particleWorkgroups);
        }

        this.dispatch(encoder, this.pipelines.clearGrid, gridWorkgroups);
        this.dispatch(encoder, this.pipelines.accumulateVolume, particleWorkgroups);
        this.dispatch(encoder, this.pipelines.finalizeVolume, gridWorkgroups);

        encoder.copyBufferToBuffer(this.particleBuffer, 0, this.particleReadbackBuffer, 0, this.particleByteSize);
        encoder.copyBufferToBuffer(this.volumeFractionBuffer, 0, this.volumeReadbackBuffer, 0, this.gridScalarByteSize);
        encoder.copyBufferToBuffer(this.densityFractionBuffer, 0, this.densityReadbackBuffer, 0, this.gridScalarByteSize);
        this.device.queue.submit([encoder.finish()]);

        await this.readback(particles, particleCount);
    }

    dispatch(encoder, pipeline, workgroups){
        let pass = encoder.beginComputePass();
        pass.setPipeline(pipeline);
        pass.setBindGroup(0, this.bindGroup);
        pass.dispatchWorkgroups(workgroups);
        pass.end();
    }

    async readback(particles, particleCount){
        await Promise.all([
            this.particleReadbackBuffer.mapAsync(GPUMapMode.READ),
            this.volumeReadbackBuffer.mapAsync(GPUMapMode.READ),
            this.densityReadbackBuffer.mapAsync(GPUMapMode.READ)
        ]);

        this.readScratch.set(new Float32Array(this.particleReadbackBuffer.getMappedRange()));
        this.volumeFractions.set(new Float32Array(this.volumeReadbackBuffer.getMappedRange()));
        this.densityFractions.set(new Float32Array(this.densityReadbackBuffer.getMappedRange()));

        this.particleReadbackBuffer.unmap();
        this.volumeReadbackBuffer.unmap();
        this.densityReadbackBuffer.unmap();

        for(let i=0; i<particleCount; i++){
            let p = particles[i];
            let o = i * this.particleStride;
            p.position.x = this.readScratch[o + 0];
            p.position.y = this.readScratch[o + 1];
            p.prevPosition.x = this.readScratch[o + 2];
            p.prevPosition.y = this.readScratch[o + 3];
            p.velocity.x = this.readScratch[o + 4];
            p.velocity.y = this.readScratch[o + 5];
            p.foam = this.readScratch[o + 6];
            p.air = this.readScratch[o + 7];
            p.density = this.readScratch[o + 8];
            p.age = this.readScratch[o + 9];
            p.agitation = this.readScratch[o + 10];
            p.cover = this.readScratch[o + 11];
        }
    }

    shaderCode(){
        return `
struct Particle {
    pos: vec2<f32>,
    prev: vec2<f32>,
    vel: vec2<f32>,
    foam: f32,
    air: f32,
    materialDensity: f32,
    age: f32,
    agitation: f32,
    cover: f32,
    pad0: vec2<f32>,
    pad1: vec4<f32>,
};

struct Params {
    sim0: vec4<f32>,
    sim1: vec4<f32>,
    grid0: vec4<f32>,
    flip0: vec4<f32>,
    glass0: vec4<f32>,
    glass1: vec4<f32>,
    foam0: vec4<f32>,
    foam1: vec4<f32>,
    overflow0: vec4<f32>,
    spare0: vec4<f32>,
    spare1: vec4<f32>,
    spare2: vec4<f32>,
    spare3: vec4<f32>,
    spare4: vec4<f32>,
    spare5: vec4<f32>,
    spare6: vec4<f32>,
};

@group(0) @binding(0) var<storage, read_write> particles: array<Particle>;
@group(0) @binding(1) var<uniform> params: Params;
@group(0) @binding(2) var<storage, read_write> accumX: array<atomic<i32>>;
@group(0) @binding(3) var<storage, read_write> accumY: array<atomic<i32>>;
@group(0) @binding(4) var<storage, read_write> weights: array<atomic<u32>>;
@group(0) @binding(5) var<storage, read_write> gridVel: array<vec4<f32>>;
@group(0) @binding(6) var<storage, read_write> prevGridVel: array<vec4<f32>>;
@group(0) @binding(7) var<storage, read_write> divergenceBuf: array<f32>;
@group(0) @binding(8) var<storage, read_write> pressure: array<f32>;
@group(0) @binding(9) var<storage, read_write> pressureTemp: array<f32>;
@group(0) @binding(10) var<storage, read_write> volumeCounts: array<atomic<u32>>;
@group(0) @binding(11) var<storage, read_write> densityCounts: array<atomic<u32>>;
@group(0) @binding(12) var<storage, read_write> volumeFractions: array<f32>;
@group(0) @binding(13) var<storage, read_write> densityFractions: array<f32>;

fn particleCount() -> u32 {
    return min(u32(params.sim0.y), u32(params.flip0.w));
}

fn gridWidth() -> i32 { return i32(params.grid0.y); }
fn gridHeight() -> i32 { return i32(params.grid0.z); }
fn cellSize() -> f32 { return params.grid0.x; }
fn gridCells() -> u32 { return u32(params.grid0.y) * u32(params.grid0.z); }

fn idxOf(x: i32, y: i32) -> u32 {
    return u32(clamp(y, 0, gridHeight() - 1) * gridWidth() + clamp(x, 0, gridWidth() - 1));
}

fn posToGrid(pos: vec2<f32>) -> vec2<f32> {
    return pos / cellSize() - vec2<f32>(0.5);
}

fn limitVector(v: vec2<f32>, maxLen: f32) -> vec2<f32> {
    let len = length(v);
    if(len > maxLen && len > 0.0001){
        return v * (maxLen / len);
    }
    return v;
}

fn worldToGlassLocal(pos: vec2<f32>) -> vec2<f32> {
    let center = params.glass0.xy;
    let angle = params.glass0.z;
    let c = cos(angle);
    let s = sin(angle);
    let d = pos - center;
    return vec2<f32>(d.x * c + d.y * s, -d.x * s + d.y * c);
}

fn glassLocalToWorld(local: vec2<f32>) -> vec2<f32> {
    let center = params.glass0.xy;
    let angle = params.glass0.z;
    let c = cos(angle);
    let s = sin(angle);
    return vec2<f32>(center.x + local.x * c - local.y * s, center.y + local.x * s + local.y * c);
}

fn glassInteriorHalfWidth(localY: f32) -> f32 {
    let y01 = clamp((localY + params.glass1.z * 0.5) / params.glass1.z, 0.0, 1.0);
    let widthAtY = params.glass1.x + (params.glass1.y - params.glass1.x) * y01;
    return max(10.0, widthAtY * 0.5 - params.glass0.w);
}

fn insideGlassInterior(pos: vec2<f32>) -> bool {
    let local = worldToGlassLocal(pos);
    let halfWidth = glassInteriorHalfWidth(local.y);
    return local.x > -halfWidth &&
        local.x < halfWidth &&
        local.y > -params.glass1.z * 0.5 &&
        local.y < params.glass1.z * 0.5 - params.glass0.w;
}

fn resolveGlass(posIn: vec2<f32>) -> vec2<f32> {
    var pos = posIn;
    var local = worldToGlassLocal(pos);
    let top = -params.glass1.z * 0.5;
    let bottom = params.glass1.z * 0.5 - params.glass0.w;
    if(local.y > top - params.glass0.w * 0.5 && local.y < bottom + params.glass0.w){
        let halfWidth = glassInteriorHalfWidth(local.y);
        let outer = halfWidth + params.glass0.w * 1.2;
        if(abs(local.x) < outer){
            local.y = min(local.y, bottom);
            if(local.y > top){
                local.x = clamp(local.x, -halfWidth, halfWidth);
            }
            pos = glassLocalToWorld(local);
        }
    }
    return pos;
}

fn resolveWorld(posIn: vec2<f32>) -> vec2<f32> {
    var pos = posIn;
    pos.x = clamp(pos.x, 0.0, params.sim0.z - 1.0);
    pos.y = max(0.0, pos.y);
    if(pos.y > params.sim1.w && !insideGlassInterior(pos)){
        pos.y = params.sim1.w;
    }
    pos.y = min(pos.y, params.sim0.w - 1.0);
    return resolveGlass(pos);
}

fn sampleGrid(pos: vec2<f32>, usePrev: bool) -> vec2<f32> {
    let gp = posToGrid(pos);
    let bx = i32(floor(gp.x));
    let by = i32(floor(gp.y));
    let fx = fract(gp.x);
    let fy = fract(gp.y);
    var v = vec2<f32>(0.0);
    for(var oy: i32 = 0; oy <= 1; oy = oy + 1){
        for(var ox: i32 = 0; ox <= 1; ox = ox + 1){
            let wx = select(1.0 - fx, fx, ox == 1);
            let wy = select(1.0 - fy, fy, oy == 1);
            let id = idxOf(bx + ox, by + oy);
            let gv = select(gridVel[id].xy, prevGridVel[id].xy, usePrev);
            v += gv * wx * wy;
        }
    }
    return v;
}

@compute @workgroup_size(64)
fn clearGrid(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    if(i >= gridCells()){
        return;
    }
    atomicStore(&accumX[i], 0);
    atomicStore(&accumY[i], 0);
    atomicStore(&weights[i], 0u);
    atomicStore(&volumeCounts[i], 0u);
    atomicStore(&densityCounts[i], 0u);
    divergenceBuf[i] = 0.0;
    volumeFractions[i] = 0.0;
    densityFractions[i] = 0.0;
}

@compute @workgroup_size(64)
fn particleToGrid(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    if(i >= particleCount()){
        return;
    }

    let p = particles[i];
    let gp = posToGrid(p.pos);
    let bx = i32(floor(gp.x));
    let by = i32(floor(gp.y));
    let fx = fract(gp.x);
    let fy = fract(gp.y);
    let scale = 1024.0;

    for(var oy: i32 = 0; oy <= 1; oy = oy + 1){
        for(var ox: i32 = 0; ox <= 1; ox = ox + 1){
            let wx = select(1.0 - fx, fx, ox == 1);
            let wy = select(1.0 - fy, fy, oy == 1);
            let w = max(0.0, wx * wy);
            let idx = idxOf(bx + ox, by + oy);
            atomicAdd(&accumX[idx], i32(p.vel.x * w * scale));
            atomicAdd(&accumY[idx], i32(p.vel.y * w * scale));
            atomicAdd(&weights[idx], u32(w * scale));
        }
    }
}

@compute @workgroup_size(64)
fn normalizeGrid(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    if(i >= gridCells()){
        return;
    }

    let w = f32(atomicLoad(&weights[i]));
    var v = vec2<f32>(0.0);
    if(w > 0.0){
        v = vec2<f32>(f32(atomicLoad(&accumX[i])), f32(atomicLoad(&accumY[i]))) / max(1.0, w);
    }
    v += params.sim1.xy * params.sim0.x;
    v *= params.flip0.y;
    gridVel[i] = vec4<f32>(limitVector(v, params.sim1.z), 0.0, w);
}

@compute @workgroup_size(64)
fn divergence(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    if(i >= gridCells()){
        return;
    }
    let x = i32(i % u32(gridWidth()));
    let y = i32(i / u32(gridWidth()));
    let left = gridVel[idxOf(x - 1, y)].x;
    let right = gridVel[idxOf(x + 1, y)].x;
    let down = gridVel[idxOf(x, y - 1)].y;
    let up = gridVel[idxOf(x, y + 1)].y;
    divergenceBuf[i] = 0.5 * ((right - left) + (up - down)) / cellSize();
}

@compute @workgroup_size(64)
fn clearPressure(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    if(i >= gridCells()){
        return;
    }
    pressure[i] = 0.0;
    pressureTemp[i] = 0.0;
}

@compute @workgroup_size(64)
fn pressureJacobi(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    if(i >= gridCells()){
        return;
    }
    let x = i32(i % u32(gridWidth()));
    let y = i32(i / u32(gridWidth()));
    let pL = pressure[idxOf(x - 1, y)];
    let pR = pressure[idxOf(x + 1, y)];
    let pD = pressure[idxOf(x, y - 1)];
    let pU = pressure[idxOf(x, y + 1)];
    let newP = (pL + pR + pD + pU - divergenceBuf[i] * params.flip0.z) * 0.25;
    pressureTemp[i] = newP;
    pressure[i] = newP;
}

@compute @workgroup_size(64)
fn subtractPressure(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    if(i >= gridCells()){
        return;
    }
    let x = i32(i % u32(gridWidth()));
    let y = i32(i / u32(gridWidth()));
    let grad = vec2<f32>(
        pressure[idxOf(x + 1, y)] - pressure[idxOf(x - 1, y)],
        pressure[idxOf(x, y + 1)] - pressure[idxOf(x, y - 1)]
    ) * (0.5 / cellSize());
    var v = gridVel[i].xy - grad;
    gridVel[i] = vec4<f32>(limitVector(v, params.sim1.z), 0.0, gridVel[i].w);
}

@compute @workgroup_size(64)
fn gridToParticle(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    if(i >= particleCount()){
        return;
    }
    var p = particles[i];
    let pic = sampleGrid(p.pos, false);
    let oldGrid = sampleGrid(p.pos, true);
    let flip = p.vel + (pic - oldGrid);
    p.vel = limitVector(mix(pic, flip, params.flip0.x), params.sim1.z);
    particles[i] = p;
}

@compute @workgroup_size(64)
fn advectParticles(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    if(i >= particleCount()){
        return;
    }
    var p = particles[i];
    let dt = params.sim0.x;
    let inGlass = insideGlassInterior(p.pos);
    var v = p.vel;

    if(inGlass){
        let angle = params.glass0.z;
        let baseDir = vec2<f32>(-sin(angle), cos(angle));
        let local = worldToGlassLocal(p.pos);
        let bottom = params.glass1.z * 0.5 - params.glass0.w;
        let basePull = clamp((bottom - local.y) / params.glass1.z, 0.0, 1.0);
        v += baseDir * basePull * params.glass1.w * dt;
        v.y -= p.foam * params.foam1.z * dt;
        if(params.overflow0.x > 0.0){
            let surfaceBias = max(0.0, 1.0 - (local.y + params.glass1.z * 0.5) / (params.glass1.z * 0.42));
            v += params.overflow0.yz * params.overflow0.x * surfaceBias * dt * 8.0;
        }
    }

    p.prev = p.pos;
    let predicted = p.pos + limitVector(v, params.sim1.z) * dt;
    let resolved = resolveWorld(predicted);
    if(length(resolved - predicted) > 0.01){
        v *= 0.35;
    }
    p.pos = resolved;
    p.vel = limitVector(v, params.sim1.z);

    let speed = length(p.vel);
    let stir = max(0.0, speed - params.foam0.x);
    let surface = clamp(1.0 - p.cover * 0.25, 0.0, 1.0);
    if(inGlass && stir > 0.0){
        p.air = min(1.0, p.air + stir * params.foam0.w * dt * (0.3 + surface * 0.7));
        p.foam = min(1.0, p.foam + stir * params.foam0.y * dt * surface);
    }
    p.air = max(0.0, p.air - p.air * params.foam1.x * dt);
    p.foam = max(0.0, p.foam - p.foam * params.foam0.z * dt);
    p.materialDensity = clamp(params.foam1.w - params.foam1.y * p.air - 0.12 * p.foam, 0.35, 1.06);
    p.agitation = speed;
    p.cover = select(0.0, max(0.0, p.cover * 0.92), inGlass);
    p.age += dt;
    particles[i] = p;
}

@compute @workgroup_size(64)
fn accumulateVolume(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    if(i >= particleCount()){
        return;
    }
    let p = particles[i];
    let gx = i32(floor(p.pos.x / cellSize()));
    let gy = i32(floor(p.pos.y / cellSize()));
    if(gx < 0 || gy < 0 || gx >= gridWidth() || gy >= gridHeight()){
        return;
    }
    let idx = idxOf(gx, gy);
    let mixture = u32(params.grid0.w);
    let beerShare = clamp(1.0 - p.air * 0.55 - p.foam * 0.16, 0.20, 1.0);
    atomicAdd(&volumeCounts[idx], u32(f32(mixture) * beerShare));
    atomicAdd(&densityCounts[idx], u32(f32(mixture) * clamp(p.materialDensity, 0.0, 1.2)));
    atomicAdd(&weights[idx], mixture);
}

@compute @workgroup_size(64)
fn finalizeVolume(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    if(i >= gridCells()){
        return;
    }
    let raw = f32(atomicLoad(&volumeCounts[i]));
    let mixRaw = max(1.0, f32(atomicLoad(&weights[i])));
    volumeFractions[i] = min(1.0, raw / 65535.0);
    densityFractions[i] = clamp(f32(atomicLoad(&densityCounts[i])) / mixRaw, 0.0, 1.2);
}
`;
    }
}

