+fn gridWidth() -> i32 { return i32(params.grid0.y); }
+fn gridHeight() -> i32 { return i32(params.grid0.z); }
+fn cellSize() -> f32 { return params.grid0.x; }
+fn gridCells() -> u32 { return u32(params.grid0.y) * u32(params.grid0.z); }
+
+fn idxOf(x: i32, y: i32) -> u32 {
+    return u32(clamp(y, 0, gridHeight() - 1) * gridWidth() + clamp(x, 0, gridWidth() - 1));
+}
+
+fn cellTypeAt(x: i32, y: i32) -> u32 {
+    return atomicLoad(&grid[idxOf(x, y)].cellType);
+}
+
+fn isFluidType(t: u32) -> bool { return t == FLUID_CELL; }
+fn isSolidType(t: u32) -> bool { return t == SOLID_CELL; }
+fn isAirType(t: u32) -> bool { return t == AIR_CELL; }
+
+fn limitVector(v: vec2<f32>, maxLen: f32) -> vec2<f32> {
+    let len = length(v);
+    if(len > maxLen && len > 0.0001){ return v * (maxLen / len); }
+    return v;
+}
+
+fn limitScalar(v: f32, maxLen: f32) -> f32 {
+    return clamp(v, -maxLen, maxLen);
+}
+
+fn worldToGlassLocal(pos: vec2<f32>) -> vec2<f32> {
+    let center = params.glass0.xy;
+    let angle = params.glass0.z;
+    let c = cos(angle);
+    let s = sin(angle);
+    let d = pos - center;
+    return vec2<f32>(d.x * c + d.y * s, -d.x * s + d.y * c);
+}
+
+fn glassLocalToWorld(local: vec2<f32>) -> vec2<f32> {
+    let center = params.glass0.xy;
+    let angle = params.glass0.z;
+    let c = cos(angle);
+    let s = sin(angle);
+    return vec2<f32>(center.x + local.x * c - local.y * s, center.y + local.x * s + local.y * c);
+}
+
+fn glassInteriorHalfWidth(localY: f32) -> f32 {
+    let y01 = clamp((localY + params.glass1.z * 0.5) / params.glass1.z, 0.0, 1.0);
+    let widthAtY = params.glass1.x + (params.glass1.y - params.glass1.x) * y01;
+    return max(10.0, widthAtY * 0.5 - params.glass0.w);
+}
+
+fn insideGlassInterior(pos: vec2<f32>) -> bool {
+    let local = worldToGlassLocal(pos);
+    let halfWidth = glassInteriorHalfWidth(local.y);
+    return local.x > -halfWidth &&
+        local.x < halfWidth &&
+        local.y > -params.glass1.z * 0.5 &&
+        local.y < params.glass1.z * 0.5 - params.glass0.w;
+}
+
+fn solidCellAt(x: i32, y: i32) -> bool {
+    if(x <= 0 || y <= 0 || x >= gridWidth() - 1 || y >= gridHeight() - 1){
+        return true;
+    }
+
+    let world = vec2<f32>((f32(x) + 0.5) * cellSize(), (f32(y) + 0.5) * cellSize());
+    if(world.y > params.sim1.w && !insideGlassInterior(world)){
+        return true;
+    }
+
+    let local = worldToGlassLocal(world);
+    let top = -params.glass1.z * 0.5;
+    let bottom = params.glass1.z * 0.5 - params.glass0.w;
+    let halfWidth = glassInteriorHalfWidth(local.y);
+    let sideBand = local.y > top &&
+        local.y < bottom &&
+        abs(local.x) >= halfWidth &&
+        abs(local.x) < halfWidth + params.glass0.w * 1.15;
+    let baseBand = local.y >= bottom &&
+        local.y < bottom + params.glass0.w * 1.45 &&
+        abs(local.x) < halfWidth + params.glass0.w * 1.25;
+
+    return sideBand || baseBand;
+}
+
+fn resolveGlass(posIn: vec2<f32>) -> vec2<f32> {
+    var pos = posIn;
+    var local = worldToGlassLocal(pos);
+    let top = -params.glass1.z * 0.5;
+    let bottom = params.glass1.z * 0.5 - params.glass0.w;
+    if(local.y > top - params.glass0.w * 0.5 && local.y < bottom + params.glass0.w){
+        let halfWidth = glassInteriorHalfWidth(local.y);
+        let outer = halfWidth + params.glass0.w * 1.2;
+        if(abs(local.x) < outer){
+            local.y = min(local.y, bottom);
+            if(local.y > top){
+                local.x = clamp(local.x, -halfWidth, halfWidth);
+            }
+            pos = glassLocalToWorld(local);
+        }
+    }
+    return pos;
+}
+
+fn resolveWorld(posIn: vec2<f32>) -> vec2<f32> {
+    var pos = posIn;
+    pos.x = clamp(pos.x, 0.0, params.sim0.z - 1.0);
+    pos.y = max(0.0, pos.y);
+    if(pos.y > params.sim1.w && !insideGlassInterior(pos)){
+        pos.y = params.sim1.w;
+    }
+    pos.y = min(pos.y, params.sim0.w - 1.0);
+    return resolveGlass(pos);
+}
+
+fn faceValid(x: i32, y: i32, component: u32) -> bool {
+    if(component == 0u){
+        let a = cellTypeAt(x, y);
+        let b = cellTypeAt(x - 1, y);
+        return !isAirType(a) || !isAirType(b);
+    }
+    let a = cellTypeAt(x, y);
+    let b = cellTypeAt(x, y - 1);
+    return !isAirType(a) || !isAirType(b);
+}
+
+fn faceValue(x: i32, y: i32, component: u32, prev: bool) -> f32 {
+    let id = idxOf(x, y);
+    if(component == 0u){
+        return select(grid[id].u, grid[id].prevU, prev);
+    }
+    return select(grid[id].v, grid[id].prevV, prev);
+}
+
+fn sampleComponent(pos: vec2<f32>, component: u32, prev: bool) -> vec2<f32> {
+    let h = cellSize();
+    let offset = select(vec2<f32>(0.5, 0.0), vec2<f32>(0.0, 0.5), component == 0u);
+    let gp = pos / h - offset;
+    let bx = i32(floor(gp.x));
+    let by = i32(floor(gp.y));
+    let fx = fract(gp.x);
+    let fy = fract(gp.y);
+
+    var value = 0.0;
+    var weightSum = 0.0;
+    for(var oy: i32 = 0; oy <= 1; oy = oy + 1){
+        for(var ox: i32 = 0; ox <= 1; ox = ox + 1){
+            let gx = bx + ox;
+            let gy = by + oy;
+            let wx = select(1.0 - fx, fx, ox == 1);
+            let wy = select(1.0 - fy, fy, oy == 1);
+            let valid = faceValid(gx, gy, component);
+            let w = wx * wy * select(0.0, 1.0, valid);
+            value += faceValue(gx, gy, component, prev) * w;
+            weightSum += w;
+        }
+    }
+
+    if(weightSum <= 0.0001){
+        return vec2<f32>(0.0, 0.0);
+    }
+    return vec2<f32>(value / weightSum, weightSum);
+}
+
+fn splatToFace(pos: vec2<f32>, component: u32, velocity: f32) {
+    let h = cellSize();
+    let offset = select(vec2<f32>(0.5, 0.0), vec2<f32>(0.0, 0.5), component == 0u);
+    let gp = pos / h - offset;
+    let bx = i32(floor(gp.x));
+    let by = i32(floor(gp.y));
+    let fx = fract(gp.x);
+    let fy = fract(gp.y);
+
+    for(var oy: i32 = 0; oy <= 1; oy = oy + 1){
+        for(var ox: i32 = 0; ox <= 1; ox = ox + 1){
+            let gx = bx + ox;
+            let gy = by + oy;
+            if(gx < 0 || gy < 0 || gx >= gridWidth() || gy >= gridHeight()){ continue; }
+            let wx = select(1.0 - fx, fx, ox == 1);
+            let wy = select(1.0 - fy, fy, oy == 1);
+            let w = max(0.0, wx * wy);
+            let id = idxOf(gx, gy);
+            if(component == 0u){
+                atomicAdd(&grid[id].accumU, i32(velocity * w * FIXED_SCALE));
+                atomicAdd(&grid[id].weightU, u32(w * FIXED_SCALE));
+            }else{
+                atomicAdd(&grid[id].accumV, i32(velocity * w * FIXED_SCALE));
+                atomicAdd(&grid[id].weightV, u32(w * FIXED_SCALE));
+            }
+        }
+    }
+}
+
+fn splatDensity(pos: vec2<f32>) {
+    let h = cellSize();
+    let gp = pos / h - vec2<f32>(0.5);
+    let bx = i32(floor(gp.x));
+    let by = i32(floor(gp.y));
+    let fx = fract(gp.x);
+    let fy = fract(gp.y);
+    for(var oy: i32 = 0; oy <= 1; oy = oy + 1){
+        for(var ox: i32 = 0; ox <= 1; ox = ox + 1){
+            let gx = bx + ox;
+            let gy = by + oy;
+            if(gx < 0 || gy < 0 || gx >= gridWidth() || gy >= gridHeight()){ continue; }
+            if(solidCellAt(gx, gy)){ continue; }
+            let wx = select(1.0 - fx, fx, ox == 1);
+            let wy = select(1.0 - fy, fy, oy == 1);
+            let w = max(0.0, wx * wy);
+            atomicAdd(&grid[idxOf(gx, gy)].densityAccum, u32(w * FIXED_SCALE));
+        }
+    }
+}
+
+@compute @workgroup_size(64)
+fn advectParticles(@builtin(global_invocation_id) id: vec3<u32>) {
+    let i = id.x;
+    if(i >= particleCount()){ return; }
+
+    var p = particles[i];
+    let dt = params.sim0.x;
+    let wasInGlass = insideGlassInterior(p.pos);
+    var v = p.vel + params.sim1.xy * dt;
+
+    if(wasInGlass){
+        let angle = params.glass0.z;
+        let downGlass = vec2<f32>(-sin(angle), cos(angle));
+        let local = worldToGlassLocal(p.pos);
+        let bottom = params.glass1.z * 0.5 - params.glass0.w;
+        let basePull = clamp((bottom - local.y) / params.glass1.z, 0.0, 1.0);
+        v += downGlass * basePull * params.glass1.w * dt;
+        v.y -= p.foam * params.foam1.z * dt;
+        if(params.overflow0.x > 0.0){
+            let surfaceBias = max(0.0, 1.0 - (local.y + params.glass1.z * 0.5) / (params.glass1.z * 0.42));
+            v += params.overflow0.yz * params.overflow0.x * surfaceBias * dt * 8.0;
+        }
+    }
+
+    p.prev = p.pos;
+    let predicted = p.pos + limitVector(v, params.sim1.z) * dt;
+    let resolved = resolveWorld(predicted);
+    if(length(resolved - predicted) > 0.01){
+        let rLocal = worldToGlassLocal(resolved);
+        let halfWidth = glassInteriorHalfWidth(rLocal.y);
+        let top = -params.glass1.z * 0.5;
+        let bottom = params.glass1.z * 0.5 - params.glass0.w;
+        let glassHit = rLocal.y > top - params.glass0.w * 0.75 &&
+            rLocal.y < bottom + params.glass0.w &&
+            abs(rLocal.x) < halfWidth + params.glass0.w * 1.4;
+        if(glassHit){
+            let angle = params.glass0.z;
+            let downGlass = vec2<f32>(-sin(angle), cos(angle));
+            let slide = max(dot(v, downGlass), params.glass1.w * 0.2);
+            let tangent = downGlass * slide;
+            let cross = (v - downGlass * dot(v, downGlass)) * 0.16;
+            v = tangent + cross;
+        }else{
+            v *= 0.26;
+        }
+    }
+
+    p.pos = resolved;
+    p.vel = limitVector(v, params.sim1.z);
+    particles[i] = p;
+}
+
+@compute @workgroup_size(64)
+fn clearGrid(@builtin(global_invocation_id) id: vec3<u32>) {
+    let i = id.x;
+    if(i >= gridCells()){ return; }
+    let x = i32(i % u32(gridWidth()));
+    let y = i32(i / u32(gridWidth()));
+
+    grid[i].prevU = grid[i].u;
+    grid[i].prevV = grid[i].v;
+    grid[i].u = 0.0;
+    grid[i].v = 0.0;
+    grid[i].pressure = 0.0;
+    grid[i].pressureTemp = 0.0;
+    grid[i].divergence = 0.0;
+    grid[i].particleDensity = 0.0;
+    grid[i].materialDensity = 0.0;
+    atomicStore(&grid[i].accumU, 0);
+    atomicStore(&grid[i].accumV, 0);
+    atomicStore(&grid[i].weightU, 0u);
+    atomicStore(&grid[i].weightV, 0u);
+    atomicStore(&grid[i].densityAccum, 0u);
+    atomicStore(&grid[i].cellType, select(AIR_CELL, SOLID_CELL, solidCellAt(x, y)));
+}
+
+@compute @workgroup_size(64)
+fn markCells(@builtin(global_invocation_id) id: vec3<u32>) {
+    let i = id.x;
+    if(i >= particleCount()){ return; }
+    let p = particles[i];
+    let gx = i32(floor(p.pos.x / cellSize()));
+    let gy = i32(floor(p.pos.y / cellSize()));
+    if(gx < 0 || gy < 0 || gx >= gridWidth() || gy >= gridHeight()){ return; }
+    if(!solidCellAt(gx, gy)){
+        atomicStore(&grid[idxOf(gx, gy)].cellType, FLUID_CELL);
+    }
+    splatDensity(p.pos);
+}
+
+@compute @workgroup_size(64)
+fn particleToGrid(@builtin(global_invocation_id) id: vec3<u32>) {
+    let i = id.x;
+    if(i >= particleCount()){ return; }
+    let p = particles[i];
+    splatToFace(p.pos, 0u, p.vel.x);
+    splatToFace(p.pos, 1u, p.vel.y);
+}
+
+@compute @workgroup_size(64)
+fn normalizeGrid(@builtin(global_invocation_id) id: vec3<u32>) {
+    let i = id.x;
+    if(i >= gridCells()){ return; }
+    let x = i32(i % u32(gridWidth()));
+    let y = i32(i / u32(gridWidth()));
+
+    let wu = f32(atomicLoad(&grid[i].weightU));
+    let wv = f32(atomicLoad(&grid[i].weightV));
+    if(wu > 0.0){
+        grid[i].u = f32(atomicLoad(&grid[i].accumU)) / wu;
+    }
+    if(wv > 0.0){
+        grid[i].v = f32(atomicLoad(&grid[i].accumV)) / wv;
+    }
+
+    if(isSolidType(cellTypeAt(x, y)) || isSolidType(cellTypeAt(x - 1, y))){
+        grid[i].u = 0.0;
+    }
+    if(isSolidType(cellTypeAt(x, y)) || isSolidType(cellTypeAt(x, y - 1))){
+        grid[i].v = 0.0;
+    }
+
+    grid[i].u = limitScalar(grid[i].u * params.flip0.y, params.flip1.w);
+    grid[i].v = limitScalar(grid[i].v * params.flip0.y, params.flip1.w);
+    grid[i].particleDensity = f32(atomicLoad(&grid[i].densityAccum)) / FIXED_SCALE;
+}
+
+@compute @workgroup_size(64)
+fn divergence(@builtin(global_invocation_id) id: vec3<u32>) {
+    let i = id.x;
+    if(i >= gridCells()){ return; }
+    if(cellTypeAt(i32(i % u32(gridWidth())), i32(i / u32(gridWidth()))) != FLUID_CELL){
+        grid[i].divergence = 0.0;
+        return;
+    }
+
+    let x = i32(i % u32(gridWidth()));
+    let y = i32(i / u32(gridWidth()));
+    var div = grid[idxOf(x + 1, y)].u - grid[idxOf(x, y)].u +
+        grid[idxOf(x, y + 1)].v - grid[idxOf(x, y)].v;
+
+    let compression = max(0.0, grid[i].particleDensity - params.flip1.x);
+    div -= compression * params.flip1.z;
+    grid[i].divergence = div;
+}
+
+@compute @workgroup_size(64)
+fn clearPressure(@builtin(global_invocation_id) id: vec3<u32>) {
+    let i = id.x;
+    if(i >= gridCells()){ return; }
+    grid[i].pressure = 0.0;
+    grid[i].pressureTemp = 0.0;
+}
+
+@compute @workgroup_size(64)
+fn pressureJacobi(@builtin(global_invocation_id) id: vec3<u32>) {
+    let i = id.x;
+    if(i >= gridCells()){ return; }
+    let x = i32(i % u32(gridWidth()));
+    let y = i32(i / u32(gridWidth()));
+    if(cellTypeAt(x, y) != FLUID_CELL){
+        grid[i].pressureTemp = 0.0;
+        return;
+    }
+
+    let tL = cellTypeAt(x - 1, y);
+    let tR = cellTypeAt(x + 1, y);
+    let tT = cellTypeAt(x, y - 1);
+    let tB = cellTypeAt(x, y + 1);
+    let sL = select(1.0, 0.0, isSolidType(tL));
+    let sR = select(1.0, 0.0, isSolidType(tR));
+    let sT = select(1.0, 0.0, isSolidType(tT));
+    let sB = select(1.0, 0.0, isSolidType(tB));
+    let s = sL + sR + sT + sB;
+    if(s <= 0.0){
+        grid[i].pressureTemp = 0.0;
+        return;
+    }
+
+    let pL = select(0.0, grid[idxOf(x - 1, y)].pressure, tL == FLUID_CELL);
+    let pR = select(0.0, grid[idxOf(x + 1, y)].pressure, tR == FLUID_CELL);
+    let pT = select(0.0, grid[idxOf(x, y - 1)].pressure, tT == FLUID_CELL);
+    let pB = select(0.0, grid[idxOf(x, y + 1)].pressure, tB == FLUID_CELL);
+    grid[i].pressureTemp = (pL * sL + pR * sR + pT * sT + pB * sB - grid[i].divergence * params.flip0.z) / s;
+}
+
+@compute @workgroup_size(64)
+fn pressureCopy(@builtin(global_invocation_id) id: vec3<u32>) {
+    let i = id.x;
+    if(i >= gridCells()){ return; }
+    grid[i].pressure = grid[i].pressureTemp;
+}
+
+@compute @workgroup_size(64)
+fn subtractPressure(@builtin(global_invocation_id) id: vec3<u32>) {
+    let i = id.x;
+    if(i >= gridCells()){ return; }
+    let x = i32(i % u32(gridWidth()));
+    let y = i32(i / u32(gridWidth()));
+
+    let leftType = cellTypeAt(x - 1, y);
+    let rightType = cellTypeAt(x, y);
+    if(isSolidType(leftType) || isSolidType(rightType)){
+        grid[i].u = 0.0;
+    }else if(isFluidType(leftType) || isFluidType(rightType)){
+        let pL = select(0.0, grid[idxOf(x - 1, y)].pressure, isFluidType(leftType));
+        let pR = select(0.0, grid[idxOf(x, y)].pressure, isFluidType(rightType));
+        grid[i].u = limitScalar(grid[i].u - (pR - pL) * params.flip1.y, params.flip1.w);
+    }else{
+        grid[i].u = 0.0;
+    }
+
+    let topType = cellTypeAt(x, y - 1);
+    let bottomType = cellTypeAt(x, y);
+    if(isSolidType(topType) || isSolidType(bottomType)){
+        grid[i].v = 0.0;
+    }else if(isFluidType(topType) || isFluidType(bottomType)){
+        let pT = select(0.0, grid[idxOf(x, y - 1)].pressure, isFluidType(topType));
+        let pB = select(0.0, grid[idxOf(x, y)].pressure, isFluidType(bottomType));
+        grid[i].v = limitScalar(grid[i].v - (pB - pT) * params.flip1.y, params.flip1.w);
+    }else{
+        grid[i].v = 0.0;
+    }
+}
+
+@compute @workgroup_size(64)
+fn gridToParticle(@builtin(global_invocation_id) id: vec3<u32>) {
+    let i = id.x;
+    if(i >= particleCount()){ return; }
+    var p = particles[i];
+
+    let picU = sampleComponent(p.pos, 0u, false);
+    let oldU = sampleComponent(p.pos, 0u, true);
+    if(picU.y > 0.0 && oldU.y > 0.0){
+        let flipU = p.vel.x + (picU.x - oldU.x);
+        p.vel.x = picU.x * (1.0 - params.flip0.x) + flipU * params.flip0.x;
+    }
+
+    let picV = sampleComponent(p.pos, 1u, false);
+    let oldV = sampleComponent(p.pos, 1u, true);
+    if(picV.y > 0.0 && oldV.y > 0.0){
+        let flipV = p.vel.y + (picV.x - oldV.x);
+        p.vel.y = picV.x * (1.0 - params.flip0.x) + flipV * params.flip0.x;
+    }
+
+    p.vel = limitVector(p.vel, params.sim1.z);
+
+    let inGlass = insideGlassInterior(p.pos);
+    let coverNow = select(
+        0.0,
+        clamp((worldToGlassLocal(p.pos).y - params.overflow0.w) / 22.0, 0.0, 5.0),
+        inGlass
+    );
+    let speed = length(p.vel);
+    let stir = max(0.0, speed - params.foam0.x);
+    let surface = clamp(1.0 - coverNow * 0.45, 0.0, 1.0);
+    if(inGlass && stir > 0.0){
+        p.air = min(1.0, p.air + stir * params.foam0.w * params.sim0.x * (0.3 + surface * 0.7));
+        p.foam = min(1.0, p.foam + stir * params.foam0.y * params.sim0.x * surface);
+    }
+    let buriedDecay = 1.0 + coverNow * coverNow * 0.32;
+    p.air = max(0.0, p.air - p.air * params.foam1.x * buriedDecay * params.sim0.x);
+    p.foam = max(0.0, p.foam - p.foam * params.foam0.z * buriedDecay * params.sim0.x);
+    p.materialDensity = clamp(params.foam1.w - params.foam1.y * p.air - 0.12 * p.foam, 0.35, 1.06);
+    p.agitation = speed;
+    p.cover = coverNow;
+    p.age += params.sim0.x;
+
+    particles[i] = p;
+}
+
+@compute @workgroup_size(64)
+fn clearVolume(@builtin(global_invocation_id) id: vec3<u32>) {
+    let i = id.x;
+    if(i >= gridCells()){ return; }
+    atomicStore(&grid[i].densityAccum, 0u);
+    atomicStore(&grid[i].volumeAccum, 0u);
+    atomicStore(&grid[i].materialAccum, 0u);
+    volumeFractions[i] = 0.0;
+    densityFractions[i] = 0.0;
+}
+
+@compute @workgroup_size(64)
+fn accumulateVolume(@builtin(global_invocation_id) id: vec3<u32>) {
+    let i = id.x;
+    if(i >= particleCount()){ return; }
+    let p = particles[i];
+    let mixture = f32(u32(params.grid0.w));
+    let beerShare = clamp(1.0 - p.air * 0.55 - p.foam * 0.16, 0.20, 1.0);
+    let matDensity = clamp(p.materialDensity, 0.0, 1.2);
+
