class WebGPUFlipSolver{
    constructor(device, config){
        this.device = device;
        this.maxParticles = config.maxParticles;
        this.particleStride = 16;
        this.particleByteSize = this.maxParticles * this.particleStride * 4;
        this.workgroupSize = 64;

        this.gridCellSize = config.gridCellSize;
        this.gridWidth = Math.ceil(config.canvasWidth / this.gridCellSize) + 1;
        this.gridHeight = Math.ceil(config.canvasHeight / this.gridCellSize) + 1;
        this.gridCells = this.gridWidth * this.gridHeight;
        this.gridCellByteSize = 96;
        this.gridByteSize = this.gridCells * this.gridCellByteSize;
        this.gridScalarByteSize = this.gridCells * 4;

        this.volumeCellSize = this.gridCellSize;
        this.volumeGridWidth = this.gridWidth;
        this.volumeGridHeight = this.gridHeight;

        this.uploadScratch = new Float32Array(this.maxParticles * this.particleStride);
        this.readScratch = new Float32Array(this.maxParticles * this.particleStride);
        this.volumeFractions = new Float32Array(this.gridCells);
        this.densityFractions = new Float32Array(this.gridCells);
        this.params = new Float32Array(64);

        this.particleBuffer = device.createBuffer({
            size: this.particleByteSize,
            usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST | GPUBufferUsage.COPY_SRC
        });
        this.particleReadbackBuffer = device.createBuffer({
            size: this.particleByteSize,
            usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST
        });
        this.paramsBuffer = device.createBuffer({
            size: this.params.byteLength,
            usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST
        });
        this.gridBuffer = device.createBuffer({
            size: this.gridByteSize,
            usage: GPUBufferUsage.STORAGE
        });
        this.volumeFractionBuffer = device.createBuffer({
            size: this.gridScalarByteSize,
            usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC
        });
        this.densityFractionBuffer = device.createBuffer({
            size: this.gridScalarByteSize,
            usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC
        });
        this.volumeReadbackBuffer = device.createBuffer({
            size: this.gridScalarByteSize,
            usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST
        });
        this.densityReadbackBuffer = device.createBuffer({
            size: this.gridScalarByteSize,
            usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST
        });

        this.createPipelines();
    }

    static async create(config){
        if(!navigator.gpu){
            throw new Error("WebGPU is required for this FLIP solver.");
        }

        let adapter = await navigator.gpu.requestAdapter({ powerPreference: "high-performance" });
        if(!adapter){
            throw new Error("No WebGPU adapter was found.");
        }

        let device = await adapter.requestDevice();
        device.lost.then((info) => {
            console.error("WebGPU device lost:", info.message);
        });

        return new WebGPUFlipSolver(device, config);
    }

    createPipelines(){
        let module = this.device.createShaderModule({ code: this.shaderCode() });
        this.bindGroupLayout = this.device.createBindGroupLayout({
            entries: [
                { binding: 0, visibility: GPUShaderStage.COMPUTE, buffer: { type: "storage" } },
                { binding: 1, visibility: GPUShaderStage.COMPUTE, buffer: { type: "uniform" } },
                { binding: 2, visibility: GPUShaderStage.COMPUTE, buffer: { type: "storage" } },
                { binding: 3, visibility: GPUShaderStage.COMPUTE, buffer: { type: "storage" } },
                { binding: 4, visibility: GPUShaderStage.COMPUTE, buffer: { type: "storage" } }
            ]
        });

        let layout = this.device.createPipelineLayout({ bindGroupLayouts: [this.bindGroupLayout] });
        let makePipeline = (entryPoint) => this.device.createComputePipeline({
            layout: layout,
            compute: { module: module, entryPoint: entryPoint }
        });

        this.pipelines = {
            advectParticles: makePipeline("advectParticles"),
            clearGrid: makePipeline("clearGrid"),
            markCells: makePipeline("markCells"),
            particleToGrid: makePipeline("particleToGrid"),
            normalizeGrid: makePipeline("normalizeGrid"),
            divergence: makePipeline("divergence"),
            clearPressure: makePipeline("clearPressure"),
            pressureJacobi: makePipeline("pressureJacobi"),
            pressureCopy: makePipeline("pressureCopy"),
            subtractPressure: makePipeline("subtractPressure"),
            gridToParticle: makePipeline("gridToParticle"),
            clearVolume: makePipeline("clearVolume"),
            accumulateVolume: makePipeline("accumulateVolume"),
            finalizeVolume: makePipeline("finalizeVolume")
        };

        this.bindGroup = this.device.createBindGroup({
            layout: this.bindGroupLayout,
            entries: [
                { binding: 0, resource: { buffer: this.particleBuffer } },
                { binding: 1, resource: { buffer: this.paramsBuffer } },
                { binding: 2, resource: { buffer: this.gridBuffer } },
                { binding: 3, resource: { buffer: this.volumeFractionBuffer } },
                { binding: 4, resource: { buffer: this.densityFractionBuffer } }
            ]
        });
    }

    uploadParticles(particles){
        let count = Math.min(particles.length, this.maxParticles);
        for(let i=0; i<count; i++){
            let p = particles[i];
            let o = i * this.particleStride;
            this.uploadScratch[o + 0] = p.position.x;
            this.uploadScratch[o + 1] = p.position.y;
            this.uploadScratch[o + 2] = p.prevPosition.x;
            this.uploadScratch[o + 3] = p.prevPosition.y;
            this.uploadScratch[o + 4] = p.velocity.x;
            this.uploadScratch[o + 5] = p.velocity.y;
            this.uploadScratch[o + 6] = p.foam || 0;
            this.uploadScratch[o + 7] = p.air || 0;
            this.uploadScratch[o + 8] = p.density || 1;
            this.uploadScratch[o + 9] = p.age || 0;
            this.uploadScratch[o + 10] = p.agitation || 0;
            this.uploadScratch[o + 11] = p.cover || 0;
            this.uploadScratch[o + 12] = 0;
            this.uploadScratch[o + 13] = 0;
            this.uploadScratch[o + 14] = 0;
            this.uploadScratch[o + 15] = 0;
        }

        if(count > 0){
            this.device.queue.writeBuffer(this.particleBuffer, 0, this.uploadScratch.buffer, 0, count * this.particleStride * 4);
        }
        return count;
    }

    writeParams(settings){
        let particleArea = Math.PI * settings.particleVolumeRadius * settings.particleVolumeRadius;
        let cellArea = this.gridCellSize * this.gridCellSize;
        let volumeFixedPoint = Math.max(1, Math.round((particleArea / cellArea) * 65535));
        let p = this.params;

        p[0] = settings.dt;
        p[1] = settings.particleCount;
        p[2] = settings.canvasWidth;
        p[3] = settings.canvasHeight;
        p[4] = settings.gravity.x;
        p[5] = settings.gravity.y;
        p[6] = settings.maxSpeed;
        p[7] = settings.tableY;
        p[8] = this.gridCellSize;
        p[9] = this.gridWidth;
        p[10] = this.gridHeight;
        p[11] = volumeFixedPoint;
        p[12] = settings.picFlipBlend;
        p[13] = settings.gridDamping;
        p[14] = settings.pressureScale;
        p[15] = settings.maxParticles;
        p[16] = settings.glass.center.x;
        p[17] = settings.glass.center.y;
        p[18] = settings.glass.angle;
        p[19] = settings.glass.wall;
        p[20] = settings.glass.topWidth;
        p[21] = settings.glass.bottomWidth;
        p[22] = settings.glass.height;
        p[23] = settings.basePull;
        p[24] = settings.foamThreshold;
        p[25] = settings.foamGeneration;
        p[26] = settings.foamDecay;
        p[27] = settings.airEntrapment;
        p[28] = settings.airVentRate;
        p[29] = settings.airDensityDrop;
        p[30] = settings.foamBuoyancy;
        p[31] = settings.baseDensity;
        p[32] = settings.overflow;
        p[33] = settings.rimOut.x;
        p[34] = settings.rimOut.y;
        p[35] = settings.surfaceLocalY;
        p[36] = settings.restDensity ?? 1.0;
        p[37] = settings.pressureApply ?? 1.0;
        p[38] = settings.driftCompensation ?? 2.0;
        p[39] = settings.gridVelocityLimit ?? settings.maxSpeed;

        this.device.queue.writeBuffer(this.paramsBuffer, 0, p.buffer, 0, p.byteLength);
    }

    async step(particles, settings){
        let particleCount = this.uploadParticles(particles);
        settings.particleCount = particleCount;

        let originalDt = settings.dt;
        let substeps = Math.max(1, settings.substeps | 0);
        settings.dt = originalDt / substeps;

        let encoder = this.device.createCommandEncoder();
        let particleWorkgroups = Math.max(1, Math.ceil(particleCount / this.workgroupSize));
        let gridWorkgroups = Math.max(1, Math.ceil(this.gridCells / this.workgroupSize));

        for(let s=0; s<substeps; s++){
            this.writeParams(settings);

            this.dispatch(encoder, this.pipelines.advectParticles, particleWorkgroups);
            this.dispatch(encoder, this.pipelines.clearGrid, gridWorkgroups);
            this.dispatch(encoder, this.pipelines.markCells, particleWorkgroups);
            this.dispatch(encoder, this.pipelines.particleToGrid, particleWorkgroups);
            this.dispatch(encoder, this.pipelines.normalizeGrid, gridWorkgroups);
            this.dispatch(encoder, this.pipelines.divergence, gridWorkgroups);
            this.dispatch(encoder, this.pipelines.clearPressure, gridWorkgroups);

            for(let i=0; i<settings.pressureIterations; i++){
                this.dispatch(encoder, this.pipelines.pressureJacobi, gridWorkgroups);
                this.dispatch(encoder, this.pipelines.pressureCopy, gridWorkgroups);
            }

            this.dispatch(encoder, this.pipelines.subtractPressure, gridWorkgroups);
            this.dispatch(encoder, this.pipelines.gridToParticle, particleWorkgroups);
        }

        this.dispatch(encoder, this.pipelines.clearVolume, gridWorkgroups);
        this.dispatch(encoder, this.pipelines.accumulateVolume, particleWorkgroups);
        this.dispatch(encoder, this.pipelines.finalizeVolume, gridWorkgroups);

        encoder.copyBufferToBuffer(this.particleBuffer, 0, this.particleReadbackBuffer, 0, this.particleByteSize);
        encoder.copyBufferToBuffer(this.volumeFractionBuffer, 0, this.volumeReadbackBuffer, 0, this.gridScalarByteSize);
        encoder.copyBufferToBuffer(this.densityFractionBuffer, 0, this.densityReadbackBuffer, 0, this.gridScalarByteSize);
        this.device.queue.submit([encoder.finish()]);

        settings.dt = originalDt;
        await this.readback(particles, particleCount);
    }

    dispatch(encoder, pipeline, workgroups){
        let pass = encoder.beginComputePass();
        pass.setPipeline(pipeline);
        pass.setBindGroup(0, this.bindGroup);
        pass.dispatchWorkgroups(workgroups);
        pass.end();
    }

    async readback(particles, particleCount){
        await Promise.all([
            this.particleReadbackBuffer.mapAsync(GPUMapMode.READ),
            this.volumeReadbackBuffer.mapAsync(GPUMapMode.READ),
            this.densityReadbackBuffer.mapAsync(GPUMapMode.READ)
        ]);

        this.readScratch.set(new Float32Array(this.particleReadbackBuffer.getMappedRange()));
        this.volumeFractions.set(new Float32Array(this.volumeReadbackBuffer.getMappedRange()));
        this.densityFractions.set(new Float32Array(this.densityReadbackBuffer.getMappedRange()));

        this.particleReadbackBuffer.unmap();
        this.volumeReadbackBuffer.unmap();
        this.densityReadbackBuffer.unmap();

        for(let i=0; i<particleCount; i++){
            let p = particles[i];
            let o = i * this.particleStride;
            p.position.x = this.readScratch[o + 0];
            p.position.y = this.readScratch[o + 1];
            p.prevPosition.x = this.readScratch[o + 2];
            p.prevPosition.y = this.readScratch[o + 3];
            p.velocity.x = this.readScratch[o + 4];
            p.velocity.y = this.readScratch[o + 5];
            p.foam = this.readScratch[o + 6];
            p.air = this.readScratch[o + 7];
            p.density = this.readScratch[o + 8];
            p.age = this.readScratch[o + 9];
            p.agitation = this.readScratch[o + 10];
            p.cover = this.readScratch[o + 11];
        }
    }

    shaderCode(){
        return `
const FLUID_CELL: u32 = 0u;
const AIR_CELL: u32 = 1u;
const SOLID_CELL: u32 = 2u;
const FIXED_SCALE: f32 = 1024.0;

struct Particle {
    pos: vec2<f32>,
    prev: vec2<f32>,
    vel: vec2<f32>,
    foam: f32,
    air: f32,
    materialDensity: f32,
    age: f32,
    agitation: f32,
    cover: f32,
    pad0: vec4<f32>,
};

struct GridCell {
    accumU: atomic<i32>,
    accumV: atomic<i32>,
    weightU: atomic<u32>,
    weightV: atomic<u32>,
    densityAccum: atomic<u32>,
    volumeAccum: atomic<u32>,
    materialAccum: atomic<u32>,
    cellType: atomic<u32>,
    u: f32,
    v: f32,
    prevU: f32,
    prevV: f32,
    pressure: f32,
    pressureTemp: f32,
    divergence: f32,
    particleDensity: f32,
    materialDensity: f32,
    pad0: f32,
    pad1: f32,
    pad2: f32,
};

struct Params {
    sim0: vec4<f32>,
    sim1: vec4<f32>,
    grid0: vec4<f32>,
    flip0: vec4<f32>,
    glass0: vec4<f32>,
    glass1: vec4<f32>,
    foam0: vec4<f32>,
    foam1: vec4<f32>,
    overflow0: vec4<f32>,
    flip1: vec4<f32>,
    spare1: vec4<f32>,
    spare2: vec4<f32>,
    spare3: vec4<f32>,
    spare4: vec4<f32>,
    spare5: vec4<f32>,
    spare6: vec4<f32>,
};

@group(0) @binding(0) var<storage, read_write> particles: array<Particle>;
@group(0) @binding(1) var<uniform> params: Params;
@group(0) @binding(2) var<storage, read_write> grid: array<GridCell>;
@group(0) @binding(3) var<storage, read_write> volumeFractions: array<f32>;
@group(0) @binding(4) var<storage, read_write> densityFractions: array<f32>;

fn particleCount() -> u32 { return min(u32(params.sim0.y), u32(params.flip0.w)); }
fn gridWidth() -> i32 { return i32(params.grid0.y); }
fn gridHeight() -> i32 { return i32(params.grid0.z); }
fn cellSize() -> f32 { return params.grid0.x; }
fn gridCells() -> u32 { return u32(params.grid0.y) * u32(params.grid0.z); }

fn idxOf(x: i32, y: i32) -> u32 {
    return u32(clamp(y, 0, gridHeight() - 1) * gridWidth() + clamp(x, 0, gridWidth() - 1));
}

fn cellTypeAt(x: i32, y: i32) -> u32 {
    return atomicLoad(&grid[idxOf(x, y)].cellType);
}

fn isFluidType(t: u32) -> bool { return t == FLUID_CELL; }
fn isSolidType(t: u32) -> bool { return t == SOLID_CELL; }
fn isAirType(t: u32) -> bool { return t == AIR_CELL; }

fn limitVector(v: vec2<f32>, maxLen: f32) -> vec2<f32> {
    let len = length(v);
    if(len > maxLen && len > 0.0001){ return v * (maxLen / len); }
    return v;
}

fn limitScalar(v: f32, maxLen: f32) -> f32 {
    return clamp(v, -maxLen, maxLen);
}

fn worldToGlassLocal(pos: vec2<f32>) -> vec2<f32> {
    let center = params.glass0.xy;
    let angle = params.glass0.z;
    let c = cos(angle);
    let s = sin(angle);
    let d = pos - center;
    return vec2<f32>(d.x * c + d.y * s, -d.x * s + d.y * c);
}

fn glassLocalToWorld(local: vec2<f32>) -> vec2<f32> {
    let center = params.glass0.xy;
    let angle = params.glass0.z;
    let c = cos(angle);
    let s = sin(angle);
    return vec2<f32>(center.x + local.x * c - local.y * s, center.y + local.x * s + local.y * c);
}

fn glassInteriorHalfWidth(localY: f32) -> f32 {
    let y01 = clamp((localY + params.glass1.z * 0.5) / params.glass1.z, 0.0, 1.0);
    let widthAtY = params.glass1.x + (params.glass1.y - params.glass1.x) * y01;
    return max(10.0, widthAtY * 0.5 - params.glass0.w);
}

fn insideGlassInterior(pos: vec2<f32>) -> bool {
    let local = worldToGlassLocal(pos);
    let halfWidth = glassInteriorHalfWidth(local.y);
    return local.x > -halfWidth &&
        local.x < halfWidth &&
        local.y > -params.glass1.z * 0.5 &&
        local.y < params.glass1.z * 0.5 - params.glass0.w;
}

fn solidCellAt(x: i32, y: i32) -> bool {
    if(x <= 0 || y <= 0 || x >= gridWidth() - 1 || y >= gridHeight() - 1){
        return true;
    }

    let world = vec2<f32>((f32(x) + 0.5) * cellSize(), (f32(y) + 0.5) * cellSize());
    if(world.y > params.sim1.w && !insideGlassInterior(world)){
        return true;
    }

    let local = worldToGlassLocal(world);
    let top = -params.glass1.z * 0.5;
    let bottom = params.glass1.z * 0.5 - params.glass0.w;
    let halfWidth = glassInteriorHalfWidth(local.y);
    let sideBand = local.y > top &&
        local.y < bottom &&
        abs(local.x) >= halfWidth &&
        abs(local.x) < halfWidth + params.glass0.w * 1.15;
    let baseBand = local.y >= bottom &&
        local.y < bottom + params.glass0.w * 1.45 &&
        abs(local.x) < halfWidth + params.glass0.w * 1.25;

    return sideBand || baseBand;
}

fn resolveGlass(posIn: vec2<f32>) -> vec2<f32> {
    var pos = posIn;
    var local = worldToGlassLocal(pos);
    let top = -params.glass1.z * 0.5;
    let bottom = params.glass1.z * 0.5 - params.glass0.w;
    if(local.y > top - params.glass0.w * 0.5 && local.y < bottom + params.glass0.w){
        let halfWidth = glassInteriorHalfWidth(local.y);
        let outer = halfWidth + params.glass0.w * 1.2;
        if(abs(local.x) < outer){
            local.y = min(local.y, bottom);
            if(local.y > top){
                local.x = clamp(local.x, -halfWidth, halfWidth);
            }
            pos = glassLocalToWorld(local);
        }
    }
    return pos;
}

fn resolveWorld(posIn: vec2<f32>) -> vec2<f32> {
    var pos = posIn;
    pos.x = clamp(pos.x, 0.0, params.sim0.z - 1.0);
    pos.y = max(0.0, pos.y);
    if(pos.y > params.sim1.w && !insideGlassInterior(pos)){
        pos.y = params.sim1.w;
    }
    pos.y = min(pos.y, params.sim0.w - 1.0);
    return resolveGlass(pos);
}

fn faceValid(x: i32, y: i32, component: u32) -> bool {
    if(component == 0u){
        let a = cellTypeAt(x, y);
        let b = cellTypeAt(x - 1, y);
        return !isAirType(a) || !isAirType(b);
    }
    let a = cellTypeAt(x, y);
    let b = cellTypeAt(x, y - 1);
    return !isAirType(a) || !isAirType(b);
}

fn faceValue(x: i32, y: i32, component: u32, prev: bool) -> f32 {
    let id = idxOf(x, y);
    if(component == 0u){
        return select(grid[id].u, grid[id].prevU, prev);
    }
    return select(grid[id].v, grid[id].prevV, prev);
}

fn sampleComponent(pos: vec2<f32>, component: u32, prev: bool) -> vec2<f32> {
    let h = cellSize();
    let offset = select(vec2<f32>(0.5, 0.0), vec2<f32>(0.0, 0.5), component == 0u);
    let gp = pos / h - offset;
    let bx = i32(floor(gp.x));
    let by = i32(floor(gp.y));
    let fx = fract(gp.x);
    let fy = fract(gp.y);

    var value = 0.0;
    var weightSum = 0.0;
    for(var oy: i32 = 0; oy <= 1; oy = oy + 1){
        for(var ox: i32 = 0; ox <= 1; ox = ox + 1){
            let gx = bx + ox;
            let gy = by + oy;
            let wx = select(1.0 - fx, fx, ox == 1);
            let wy = select(1.0 - fy, fy, oy == 1);
            let valid = faceValid(gx, gy, component);
            let w = wx * wy * select(0.0, 1.0, valid);
            value += faceValue(gx, gy, component, prev) * w;
            weightSum += w;
        }
    }

    if(weightSum <= 0.0001){
        return vec2<f32>(0.0, 0.0);
    }
    return vec2<f32>(value / weightSum, weightSum);
}

fn splatToFace(pos: vec2<f32>, component: u32, velocity: f32) {
    let h = cellSize();
    let offset = select(vec2<f32>(0.5, 0.0), vec2<f32>(0.0, 0.5), component == 0u);
    let gp = pos / h - offset;
    let bx = i32(floor(gp.x));
    let by = i32(floor(gp.y));
    let fx = fract(gp.x);
    let fy = fract(gp.y);

    for(var oy: i32 = 0; oy <= 1; oy = oy + 1){
        for(var ox: i32 = 0; ox <= 1; ox = ox + 1){
            let gx = bx + ox;
            let gy = by + oy;
            if(gx < 0 || gy < 0 || gx >= gridWidth() || gy >= gridHeight()){ continue; }
            let wx = select(1.0 - fx, fx, ox == 1);
            let wy = select(1.0 - fy, fy, oy == 1);
            let w = max(0.0, wx * wy);
            let id = idxOf(gx, gy);
            if(component == 0u){
                atomicAdd(&grid[id].accumU, i32(velocity * w * FIXED_SCALE));
                atomicAdd(&grid[id].weightU, u32(w * FIXED_SCALE));
            }else{
                atomicAdd(&grid[id].accumV, i32(velocity * w * FIXED_SCALE));
                atomicAdd(&grid[id].weightV, u32(w * FIXED_SCALE));
            }
        }
    }
}

fn splatDensity(pos: vec2<f32>) {
    let h = cellSize();
    let gp = pos / h - vec2<f32>(0.5);
    let bx = i32(floor(gp.x));
    let by = i32(floor(gp.y));
    let fx = fract(gp.x);
    let fy = fract(gp.y);
    for(var oy: i32 = 0; oy <= 1; oy = oy + 1){
        for(var ox: i32 = 0; ox <= 1; ox = ox + 1){
            let gx = bx + ox;
            let gy = by + oy;
            if(gx < 0 || gy < 0 || gx >= gridWidth() || gy >= gridHeight()){ continue; }
            if(solidCellAt(gx, gy)){ continue; }
            let wx = select(1.0 - fx, fx, ox == 1);
            let wy = select(1.0 - fy, fy, oy == 1);
