const { chromium } = require('playwright');
async function run(name, holdMs, aimX, aimY) {
  const browser = await chromium.launch({ headless: true, args: ['--enable-unsafe-webgpu', '--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1200, height: 760 } });
  const logs = [];
  page.on('console', msg => logs.push(`${msg.type()}: ${msg.text()}`));
  page.on('pageerror', err => logs.push(`pageerror: ${err.stack || err.message}`));
  await page.goto(`http://127.0.0.1:8080/Main.html?${name}`, { waitUntil: 'networkidle', timeout: 30000 });
  await page.waitForTimeout(500);
  await page.evaluate(([x, y]) => {
    window.playground.onMouseMove(new Vector2(x, y));
    window.playground.setHold(true);
  }, [aimX, aimY]);
  await page.waitForTimeout(holdMs);
  await page.evaluate(() => window.playground.setHold(false));
  await page.waitForTimeout(1200);
  const state = await page.evaluate(() => {
    const sim = window.playground?.simulation;
    const particles = sim?.particles || [];
    let maxSpeed = 0, nanCount = 0, inGlass = 0, foam = 0, air = 0, density = 0, foamVisible = 0;
    for (const p of particles) {
      const speed = Math.hypot(p.velocity.x, p.velocity.y);
      if (!Number.isFinite(p.position.x) || !Number.isFinite(p.position.y) || !Number.isFinite(speed)) nanCount++;
      maxSpeed = Math.max(maxSpeed, speed);
      if (sim.isInsideGlassInterior(p.position)) inGlass++;
      foam += p.foam || 0;
      air += p.air || 0;
      density += p.density || 0;
      if ((p.foam || 0) > sim.FOAM_RENDER_MIN) foamVisible++;
    }
    return {
      particles: particles.length,
      inGlass,
      nanCount,
      maxSpeed,
      avgFoam: particles.length ? foam / particles.length : 0,
      avgAir: particles.length ? air / particles.length : 0,
      avgDensity: particles.length ? density / particles.length : 0,
      foamVisible,
      volumeStats: sim.volumeStats,
      bottleVolumeL: sim.bottleVolumeL,
      metrics: document.getElementById('metrics')?.textContent ?? null
    };
  });
  await page.screenshot({ path: `/tmp/${name}.png`, fullPage: false });
  await browser.close();
  return { name, state, logs };
}
